mapper.select:
select order_no, buyer_id, seller_id, goods_id, goods_title, price_fen,
       pay_type, status, pickup_point, create_time, pay_time
from tb_campus_order where order_no = #{orderNo}

mapper.update:
update tb_campus_order

    pay_type = #{payType},
    pay_time = now(),
    status = #{toStatus}

where order_no = #{orderNo} and status = #{fromStatus}

mapper.select:
select order_no, buyer_id, seller_id, goods_id, goods_title, price_fen,
       pay_type, status, pickup_point, create_time
from tb_campus_order
where buyer_id = #{userId} or seller_id = #{userId}
order by create_time desc
limit #{limit}
